public class LeakyCacheManager {
    // STATIC FIELD LEAK: The map outlives any single application lifecycle or request
    private static final Map<String, byte[]> memoryCache = new HashMap<>();

    public void cacheData(String key, byte[] data) {
        // Unbounded growth without eviction policy or size limits
        memoryCache.put(key, data);
    }

    // PRODUCTION FIX: Use WeakHashMap or a bounded cache like Caffeine with time-to-live
    private final Cache<String, byte[]> safeCache = Caffeine.newBuilder()
        .maximumSize(10_000)
        .expireAfterWrite(10, TimeUnit.MINUTES)
        .build();

    public void cacheDataSafely(String key, byte[] data) {
        safeCache.put(key, data);
    }
}
